-- South Dakota. The state had two stops.
--
-- World's Largest Pheasant dropped: already here as world-s-largest-pheasant,
-- the apostrophe hiding it from the slug check for the eighth time.
--
-- Mount Moriah Cemetery goes in as mount-moriah-cemetery-deadwood, because
-- Philadelphia holds the plain slug. Deadwood's is where Wild Bill Hickok and
-- Calamity Jane are buried; Philadelphia's is a much larger Victorian cemetery
-- that was abandoned for decades. Both real, neither the other.
--
-- Fifth state needing two timezones. The line follows the Missouri River, so
-- -100.5 is the split: it keeps Pierre on the Central side where it belongs
-- and puts the whole Black Hills on Mountain. 86 Mountain, 33 Central.
--
-- Six proximity flags kept, all genuine. Deadwood in particular puts the
-- original site of the saloon where Hickok was shot 43 metres from a brothel
-- museum, because that is one short street.
--
-- 119 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('The World''s Only Corn Palace', 'the-worlds-only-corn-palace', 'roadside-oddities', 43.71471, -98.02508, 'Mitchell', 'SD', 'Mitchell''s landmark building is redecorated with enormous exterior murals made from corn, grain and other plant material. The designs change regularly, turning a civic arena into one of the country''s strangest pieces of agricultural architecture.', 'open', 'https://cornpalace.com/', null, 'America/Chicago', now()),
  ('Mitchell Indigenous Archaeological Site & Museum', 'mitchell-indigenous-archaeological-site-museum', 'weird-history', 43.7421, -98.0333, 'Mitchell', 'SD', 'An active archaeological site preserves the remains of a village occupied roughly 1,000 years ago along Lake Mitchell. Visitors can see excavations, reconstructed structures and artifacts that make the site substantially more than a conventional local-history museum.', 'limited', 'https://www.mitchellindianvillage.org/', null, 'America/Chicago', now()),
  ('Porter Sculpture Park', 'porter-sculpture-park', 'roadside-oddities', 43.66402, -97.18049, 'Montrose', 'SD', 'More than 60 handmade metal sculptures rise from the prairie, including giant animals, strange figures and a massive bull''s head. Artist Wayne Porter created the entire outdoor collection and continues adding works to the site.', 'limited', 'https://portersculpturepark.com/', null, 'America/Chicago', now()),
  ('Dignity: Of Earth & Sky', 'dignity-of-earth-sky', 'roadside-oddities', 43.78701, -99.33821, 'Chamberlain', 'SD', 'This 50-foot stainless-steel figure overlooks the Missouri River and honors the cultures of the Lakota and Dakota people. Its enormous star quilt changes appearance as diamond-shaped panels move and reflect the surrounding sky.', 'open', 'https://southdakota.com/profile/dignity-of-earth-sky/', null, 'America/Chicago', now()),
  ('Aktá Lakota Museum & Cultural Center', 'akt-lakota-museum-cultural-center', 'weird-history', 43.82556, -99.32444, 'Chamberlain', 'SD', 'The museum presents Northern Plains history and contemporary Lakota, Dakota and Nakota culture through artifacts, art and interpretation. The collection is especially useful as cultural context for travelers visiting Indigenous historic and sacred sites elsewhere in the state.', 'open', 'https://aktalakota.stjo.org/', null, 'America/Chicago', now()),
  ('Pioneer Auto Show', 'pioneer-auto-show', 'museums', 43.88609, -100.70697, 'Murdo', 'SD', 'This sprawling roadside collection contains classic automobiles, motorcycles, tractors, antique machinery and rooms of unexpected historical objects. What began as a car collection grew into a multi-building time capsule of transportation and prairie life.', 'limited', 'https://www.pioneerautoshow.com/', null, 'America/Denver', now()),
  ('South Dakota''s Original 1880 Town', 'south-dakotas-original-1880-town', 'museums', 43.88363, -101.14014, 'Midland', 'SD', 'Dozens of historic frontier buildings have been assembled into a walkable Old West town beside Interstate 90. The site mixes relocated structures, period artifacts, movie memorabilia and recreated streets into an unusually elaborate roadside settlement.', 'limited', 'https://www.1880town.com/', null, 'America/Denver', now()),
  ('Skeleton Man Walking a Skeleton Dinosaur', 'skeleton-man-walking-a-skeleton-dinosaur', 'roadside-oddities', 43.88706, -101.13181, 'Midland', 'SD', 'A skeletal human figure appears to lead an equally skeletal dinosaur beside Interstate 90 near the 1880 Town. The absurd pairing makes this one of the state''s more surreal quick roadside photo stops.', 'roadside', 'https://www.1880town.com/', null, 'America/Denver', now()),
  ('Storybook Land & Land of Oz', 'storybook-land-land-of-oz', 'roadside-oddities', 45.49241, -98.51939, 'Aberdeen', 'SD', 'This city-run park fills its grounds with oversized nursery-rhyme scenes and an elaborate Wizard of Oz area. Visitors can enter Dorothy''s house and pass through a simulated tornado before emerging into Munchkin Land.', 'limited', 'https://www.aberdeen.sd.us/286/Storybook-Land-Attractions', null, 'America/Chicago', now()),
  ('International Vinegar Museum', 'international-vinegar-museum', 'museums', 45.49663, -97.49146, 'Roslyn', 'SD', 'The museum describes itself as the world''s first and only museum dedicated entirely to vinegar. Displays cover vinegar making, unusual uses, international varieties, vinegar-based art and tastings.', 'limited', 'https://www.internationalvinegarmuseum.com/', null, 'America/Chicago', now()),
  ('Lemmon Petrified Wood Park & Museum', 'lemmon-petrified-wood-park-museum', 'roadside-oddities', 45.93944, -102.15862, 'Lemmon', 'SD', 'Entire towers, arches, sculptures and structures were assembled from petrified wood, fossils and stone during the 1930s. The result is a city-block-sized landscape that looks somewhere between a geological garden and a fantasy ruin.', 'open', 'https://www.lemmonsd.com/', null, 'America/Denver', now()),
  ('John Lopez Studio', 'john-lopez-studio', 'roadside-oddities', 45.94173, -102.15934, 'Lemmon', 'SD', 'Sculptor John Lopez turns scrap iron, discarded machinery and other metal into detailed Western animals and figures. His studio gives travelers a chance to see the strange mechanical textures behind sculptures found elsewhere around northwestern South Dakota.', 'limited', 'https://johnlopezstudio.com/', null, 'America/Denver', now()),
  ('Hugh Glass Monument', 'hugh-glass-monument', 'folklore', 45.74055, -102.23199, 'Shadehill', 'SD', 'A monument near Shadehill Reservoir marks the region where frontiersman Hugh Glass was mauled by a grizzly bear in 1823 and later began his legendary survival journey. The event became the basis for generations of frontier storytelling and eventually inspired The Revenant.', 'open', 'https://www.travelsouthdakota.com/trip-ideas/follow-trail-hugh-glass-south-dakotas-revenant', null, 'America/Denver', now()),
  ('Center of the Nation Monument', 'center-of-the-nation-monument', 'roadside-oddities', 44.67444, -103.85276, 'Belle Fourche', 'SD', 'A 21-foot granite compass rose celebrates Belle Fourche''s claim as the geographic center of the 50 United States. It is a visitor-friendly monument to a point that is actually located miles away on private ranchland.', 'open', 'https://www.visitbellefourche.com/attraction/center-of-the-nation-monument/', null, 'America/Denver', now()),
  ('Actual Geographic Center of the 50 United States', 'actual-geographic-center-of-the-50-united-states', 'roadside-oddities', 44.96719, -103.77157, 'Belle Fourche', 'SD', 'The calculated geographic center of all 50 states lies in a pasture roughly 20 miles north of Belle Fourche and is marked by a small survey marker and flag. The point is on private land; obtain current directions and permission guidance locally and never treat the coordinates as unrestricted access.', 'private', 'https://www.visitbellefourche.com/attraction/center-of-the-nation-monument/', null, 'America/Denver', now()),
  ('St. Peter''s Rock Grotto', 'st-peters-rock-grotto', 'folklore', 43.72583, -97.68722, 'Farmer', 'SD', 'A remarkable complex of stone shrines, towers and religious structures was built beside St. Peter''s Catholic Church using local rock and concrete. Its handmade forms turn the small prairie churchyard into an elaborate folk-art landscape.', 'limited', 'https://npgallery.nps.gov/GetAsset/fea4bdac-6071-40b7-bae3-8f55cb451218/', null, 'America/Chicago', now()),
  ('Devil''s Gulch', 'devils-gulch', 'folklore', 43.72287, -96.49623, 'Garretson', 'SD', 'Local tradition claims Jesse James escaped a pursuing posse by jumping his horse across this quartzite gorge after the 1876 Northfield bank raid. Historians dispute the dramatic leap, but the named chasm and its long-running legend remain firmly embedded in regional folklore.', 'open', 'https://www.visitgarretsonsd.com/devils-gulch', null, 'America/Chicago', now()),
  ('Palisades State Park', 'palisades-state-park', 'roadside-oddities', 43.68764, -96.51717, 'Garretson', 'SD', 'Split Rock Creek cuts through billion-year-old Sioux quartzite, forming vertical pink-red cliffs and narrow rock formations unlike most of eastern South Dakota. The park also preserves traces of a vanished mill town and a short-lived nineteenth-century silver rush.', 'open', 'https://gfp.sd.gov/parks/detail/palisades-state-park/', null, 'America/Chicago', now()),
  ('Good Earth State Park at Blood Run', 'good-earth-state-park-at-blood-run', 'weird-history', 43.47997, -96.61351, 'Sioux Falls', 'SD', 'Blood Run is one of the largest known Oneota cultural sites in the upper Midwest and was a major Indigenous settlement, gathering place and trade center centuries before modern Sioux Falls. The visitor center and trails interpret a landscape whose archaeological importance is easy to miss from the surrounding suburbs.', 'open', 'https://gfp.sd.gov/parks/detail/good-earth-state-park/', null, 'America/Chicago', now()),
  ('Spirit Mound Historic Prairie', 'spirit-mound-historic-prairie', 'weird-history', 42.86761, -96.95443, 'Vermillion', 'SD', 'Lewis and Clark climbed this isolated prairie hill in 1804 after hearing Indigenous accounts of powerful spirits or little people associated with the place. The mound remains one of the relatively few identifiable landscape features where visitors can closely retrace the expedition''s route on foot.', 'open', 'https://gfp.sd.gov/parks/detail/spirit-mound-historic-prairie/', null, 'America/Chicago', now()),
  ('Sica Hollow State Park', 'sica-hollow-state-park', 'folklore', 45.7421, -97.24267, 'Sisseton', 'SD', 'Dark red water, unusual springs and dense forest helped give Sica Hollow a long reputation as an uncanny landscape. The park''s Trail of the Spirits interprets the natural setting while regional Dakota traditions and later settler stories contributed to its supernatural reputation.', 'open', 'https://gfp.sd.gov/parks/detail/sica-hollow-state-park/', null, 'America/Chicago', now()),
  ('Bear Butte', 'bear-butte', 'weird-history', 44.45989, -103.4509, 'Sturgis', 'SD', 'Known as Mato Paha to the Lakota and Noahvose to the Cheyenne, Bear Butte is sacred to numerous Indigenous nations and remains an active place of prayer and ceremony. Visitors must stay respectful, leave offerings undisturbed and not photograph prayer cloths or tobacco ties.', 'open', 'https://gfp.sd.gov/parks/detail/bear-butte-state-park/', null, 'America/Denver', now()),
  ('Crazy Horse Memorial', 'crazy-horse-memorial', 'roadside-oddities', 43.83662, -103.6234, 'Crazy Horse', 'SD', 'An enormous mountain carving of Crazy Horse has been under construction in the Black Hills since 1948. The unfinished sculpture, museums and ongoing work make the site as much a record of a decades-long monumental project as a finished attraction.', 'open', 'https://crazyhorsememorial.org/', null, 'America/Denver', now()),
  ('Mount Rushmore National Memorial', 'mount-rushmore-national-memorial', 'weird-history', 43.87895, -103.45983, 'Keystone', 'SD', 'Four presidential faces carved into Black Hills granite form one of the country''s most recognizable pieces of monumental sculpture. The site also carries a complicated history involving Indigenous land, federal monument-building and the engineering required to reshape the mountain.', 'open', 'https://www.nps.gov/moru/', null, 'America/Denver', now()),
  ('Big Thunder Gold Mine', 'big-thunder-gold-mine', 'weird-history', 43.89502, -103.41717, 'Keystone', 'SD', 'Visitors descend into a nineteenth-century Black Hills gold mine where hand drilling, blasting and narrow underground workings are interpreted on guided tours. The preserved mine provides an unusually direct look at the physical environment behind the region''s gold-rush history.', 'limited', 'https://www.bigthundermine.com/', null, 'America/Denver', now()),
  ('Cosmos Mystery Area', 'cosmos-mystery-area', 'roadside-oddities', 43.92318, -103.42041, 'Rapid City', 'SD', 'The Mystery House is deliberately built and staged so visitors appear to stand at impossible angles while balls seem to roll uphill. It is a classic American gravity-hill-style attraction where perspective and construction create the illusion that normal physics has stopped working.', 'limited', 'https://cosmosmysteryarea.com/', null, 'America/Denver', now()),
  ('Dinosaur Park', 'dinosaur-park', 'roadside-oddities', 44.07796, -103.24584, 'Rapid City', 'SD', 'Huge concrete dinosaurs created as a Works Progress Administration-era tourist attraction stand along a ridge overlooking Rapid City. The intentionally old-fashioned sculptures preserve the way dinosaurs were imagined for roadside visitors in the 1930s.', 'open', 'https://www.loc.gov/pictures/item/sd0045/', null, 'America/Denver', now()),
  ('Reptile Gardens', 'reptile-gardens', 'roadside-oddities', 43.99036, -103.27169, 'Rapid City', 'SD', 'This long-running Black Hills attraction specializes in snakes, crocodilians and other reptiles, with a giant dome anchoring the grounds. Its unusual concentration of reptile exhibits has made it a classic piece of South Dakota roadside-tourism history.', 'limited', 'https://www.reptilegardens.com/', null, 'America/Denver', now()),
  ('Chapel in the Hills', 'chapel-in-the-hills', 'roadside-oddities', 44.0484, -103.29871, 'Rapid City', 'SD', 'A full-scale wooden stave church modeled after Norway''s medieval Borgund church stands unexpectedly in the Black Hills. Its steep rooflines, carved details and Scandinavian setting make it look transported from another continent.', 'open', 'https://www.chapel-in-the-hills.org/', null, 'America/Denver', now()),
  ('Museum of Geology', 'museum-of-geology', 'museums', 44.07371, -103.20613, 'Rapid City', 'SD', 'South Dakota Mines displays dinosaurs, marine reptiles, ancient mammals, minerals and fossils recovered from the region''s exceptionally rich geology. It is a useful stop for understanding what is actually buried beneath many of OddWay''s Badlands and fossil destinations.', 'open', 'https://www.sdsmt.edu/admissions-aid/visit-mines/index.html', null, 'America/Denver', now()),
  ('South Dakota Air and Space Museum', 'south-dakota-air-and-space-museum', 'weird-history', 44.13356, -103.07314, 'Box Elder', 'SD', 'Aircraft, missiles and Cold War equipment are displayed beside Ellsworth Air Force Base, including material connected with the Minuteman missile system. Because of its location next to an active military installation, visitors should follow current access and security instructions.', 'limited', 'https://www.sdairandspacemuseum.com/', null, 'America/Denver', now()),
  ('Minuteman Missile National Historic Site Visitor Center', 'minuteman-missile-national-historic-site-visitor-center', 'weird-history', 43.84451, -101.90127, 'Philip', 'SD', 'Exhibits introduce the enormous hidden network of nuclear missiles that once sat on constant alert beneath the Great Plains. It is the best orientation stop before visiting the preserved Delta-01 control facility and Delta-09 missile silo.', 'open', 'https://www.nps.gov/mimi/planyourvisit/visitorcenters.htm', null, 'America/Denver', now()),
  ('Delta-01 Launch Control Facility', 'delta-01-launch-control-facility', 'weird-history', 43.87754, -101.95988, 'Wall', 'SD', 'This deceptively ordinary-looking fenced compound once controlled a flight of ten Minuteman nuclear missiles, with the actual launch control center buried 31 feet underground. Visitors may walk to the gate, while entry and underground access require a reserved ranger-led tour.', 'limited', 'https://www.nps.gov/places/delta-01.htm', null, 'America/Denver', now()),
  ('Delta-09 Missile Silo', 'delta-09-missile-silo', 'weird-history', 43.93142, -102.15992, 'Wall', 'SD', 'A preserved Minuteman II missile remains visible beneath a glass enclosure inside its original launch silo. The quiet prairie setting makes the scale of the former nuclear missile field particularly unsettling.', 'open', 'https://www.nps.gov/places/delta-09.htm', null, 'America/Denver', now()),
  ('Giant Prairie Dog', 'giant-prairie-dog', 'roadside-oddities', 43.82158, -101.90011, 'Philip', 'SD', 'A six-ton concrete prairie dog towers roughly 12 feet above the Badlands Ranch Store. Built in 1959, it is a surviving example of the oversized animal statues that once competed for the attention of cross-country motorists.', 'open', 'https://badlandsranchstore.com/', null, 'America/Denver', now()),
  ('Wall Drug', 'wall-drug', 'roadside-oddities', 43.99284, -102.24176, 'Wall', 'SD', 'What began as a small drugstore became an enormous roadside complex advertised by hundreds of miles of famous highway signs. Inside and around the property are Western displays, mechanical figures, giant photo props and enough deliberate kitsch to make the store an attraction in its own right.', 'open', 'https://www.walldrug.com/', null, 'America/Denver', now()),
  ('Wall Drug Dinosaur', 'wall-drug-dinosaur', 'roadside-oddities', 43.98736, -102.23416, 'Wall', 'SD', 'A huge green dinosaur stands near Interstate 90 as an old-school advertisement for Wall Drug. The giant concrete creature is separate enough from the main store to function as its own roadside landmark.', 'roadside', 'https://www.walldrug.com/', null, 'America/Denver', now()),
  ('Yellow Mounds Overlook', 'yellow-mounds-overlook', 'roadside-oddities', 43.84334, -102.19457, 'Badlands National Park', 'SD', 'Bands of yellow, purple, gray and red sediment create one of the strangest color shifts in Badlands National Park. The formations expose an ancient weathered soil layer and look dramatically different from the pale pinnacles elsewhere in the park.', 'open', 'https://www.nps.gov/badl/', null, 'America/Denver', now()),
  ('Fossil Exhibit Trail', 'fossil-exhibit-trail', 'weird-history', 43.77229, -102.00302, 'Badlands National Park', 'SD', 'A short boardwalk displays replicas and interpretation of extinct animals found in the White River Badlands. It connects the bizarre exposed landscape with the oreodonts, ancient mammals and other fossils that made the region scientifically famous.', 'open', 'https://www.nps.gov/places/fossil-exhibit-trailhead.htm', null, 'America/Denver', now()),
  ('Scenic Ghost Town', 'scenic-ghost-town', 'weird-history', 43.78025, -102.55522, 'Scenic', 'SD', 'Scenic retains an old rail depot, jail cells and weathered commercial buildings from a community that declined almost to abandonment. Much of the town was sold as a single property in 2011, so travelers should remain on lawful public roads and never enter buildings or private land.', 'roadside', 'https://www.travelsouthdakota.com/trip-ideas/abandoned-beauty-ghost-towns-structures-south-dakota', null, 'America/Denver', now()),
  ('Firehenge', 'firehenge', 'roadside-oddities', 43.83986, -101.52183, 'Kadoka', 'SD', 'Old fire trucks stand vertically in a Stonehenge-like circle with an aircraft positioned at the center. The intentionally bizarre installation opened as a modern roadside attraction and even embraces tongue-in-cheek extraterrestrial lore in its official story.', 'limited', 'https://www.firehengesd.com/', null, 'America/Denver', now()),
  ('Wounded Knee Massacre Memorial and Cemetery', 'wounded-knee-massacre-memorial-and-cemetery', 'weird-history', 43.14244, -102.36495, 'Wounded Knee', 'SD', 'The cemetery and memorial overlook the site where U.S. troops killed hundreds of Lakota people on December 29, 1890. This is a sacred memorial landscape rather than a conventional attraction; visit quietly, follow local guidance and treat graves and memorial objects with respect.', 'limited', 'https://www.doi.gov/ocl/s-2088', null, 'America/Denver', now()),
  ('The Mammoth Site', 'the-mammoth-site', 'weird-history', 43.42462, -103.48321, 'Hot Springs', 'SD', 'More than 60 mammoths and many other Ice Age animals have been uncovered in an ancient sinkhole preserved inside a working research facility. Visitors walk around the active bone bed rather than seeing fossils removed into a conventional display case.', 'open', 'https://mammothsite.org/', null, 'America/Denver', now()),
  ('Wind Cave National Park — Natural Entrance & Visitor Center', 'wind-cave-national-park-natural-entrance-visitor-center', 'roadside-oddities', 43.55611, -103.47722, 'Hot Springs', 'SD', 'Wind Cave contains an immense underground maze famous for delicate boxwork formations, while the small natural entrance carries deep importance in Lakota oral tradition. Cave access is controlled through park tours, and the surrounding prairie is also protected habitat.', 'limited', 'https://www.nps.gov/wica/', null, 'America/Denver', now()),
  ('Jewel Cave National Monument', 'jewel-cave-national-monument', 'roadside-oddities', 43.72962, -103.82963, 'Custer', 'SD', 'Hundreds of miles of mapped passages make Jewel Cave one of the world''s longest known cave systems. Guided routes reveal calcite crystals, narrow passages and an underground scale that is almost impossible to appreciate from the surface.', 'limited', 'https://www.nps.gov/jeca/', null, 'America/Denver', now()),
  ('Sanford Lab Homestake Visitor Center', 'sanford-lab-homestake-visitor-center', 'weird-history', 44.35209, -103.76367, 'Lead', 'SD', 'The visitor center overlooks the enormous Homestake Open Cut and explains how one of North America''s deepest gold mines became a major underground physics laboratory. Exhibits connect mining machinery with experiments that search for dark matter, neutrinos and other elusive phenomena nearly a mile underground.', 'open', 'https://sanfordlab.org/about-visitor-center', null, 'America/Denver', now()),
  ('Broken Boot Gold Mine', 'broken-boot-gold-mine', 'haunted', 44.37072, -103.74277, 'Deadwood', 'SD', 'Guided tours enter century-old mine workings beneath the Black Hills and interpret the dangerous conditions faced by early miners. The operator also offers candlelight ghost tours, making it one of the state''s few paranormal-oriented experiences attached to a genuine historic underground site.', 'limited', 'https://brokenbootgoldmine.com/', null, 'America/Denver', now()),
  ('Mount Moriah Cemetery', 'mount-moriah-cemetery-deadwood', 'weird-history', 44.37611, -103.72556, 'Deadwood', 'SD', 'Deadwood''s hillside cemetery holds Wild Bill Hickok, Calamity Jane, Seth Bullock, Sol Star and thousands of other residents of the mining town. Chinese, Jewish, pauper and mass-grave sections make the cemetery a broader record of frontier Deadwood than its celebrity graves alone suggest.', 'limited', 'https://www.deadwood.com/business/attractions/mount-moriah-cemetery/', null, 'America/Denver', now()),
  ('Adams Museum', 'adams-museum', 'weird-history', 44.37584, -103.72949, 'Deadwood', 'SD', 'This 1930 museum preserves some of the Black Hills'' strangest artifacts, including the mysterious Thoen Stone, a large gold nugget and a rare plesiosaur specimen. Its collection gives context to Deadwood''s gold-rush mythology while retaining the oddities that made early regional museums memorable.', 'open', 'https://www.deadwoodhistory.com/about-us/properties/adams-museum/', null, 'America/Denver', now()),
  ('World''s Largest Bigfoot at Dahl''s Chainsaw Art', 'worlds-largest-bigfoot-at-dahls-chainsaw-art', 'cryptids', 43.89116, -103.42674, 'Keystone', 'SD', 'A towering chainsaw-carved Bigfoot stands among the enormous wooden creatures at Dahl''s in Keystone. The oversized sasquatch gives South Dakota a legitimate cryptid-themed roadside stop even though the state has comparatively little location-specific Bigfoot lore.', 'open', 'https://www.travelsouthdakota.com/trip-ideas/awesome-roadside-attractions', null, 'America/Denver', now()),
  ('National Presidential Wax Museum', 'national-presidential-wax-museum', 'museums', 43.88832, -103.42611, 'Keystone', 'SD', 'Dozens of life-size wax figures recreate scenes involving U.S. presidents, turning political history into a collection of carefully staged human replicas. The museum''s uncanny figures and proximity to Mount Rushmore make it a particularly fitting OddWay companion stop.', 'limited', 'https://www.presidentialwaxmuseum.com/', null, 'America/Denver', now()),
  ('Rushmore Borglum Story', 'rushmore-borglum-story', 'weird-history', 43.89098, -103.42663, 'Keystone', 'SD', 'This museum focuses on sculptor Gutzon Borglum and the difficult process of carving Mount Rushmore into Black Hills granite. Exhibits and models emphasize the blasting, drilling and larger-than-life personality behind one of America''s strangest monumental construction projects.', 'limited', 'https://www.rushmoreborglum.com/', null, 'America/Denver', now()),
  ('Museum at Black Hills Institute', 'museum-at-black-hills-institute', 'museums', 43.93332, -103.57561, 'Hill City', 'SD', 'The Black Hills Institute displays dinosaurs, marine reptiles and other fossils connected with one of the world''s best-known commercial paleontology organizations. Its collections make Hill City an important stop in the complicated South Dakota story of fossil hunting, preparation and ownership.', 'limited', 'https://www.bhigr.com/museum/', null, 'America/Denver', now()),
  ('Black Hills Central Railroad — 1880 Train', 'black-hills-central-railroad-1880-train', 'roadside-oddities', 43.93249, -103.57318, 'Hill City', 'SD', 'Historic steam locomotives haul passenger cars through the Black Hills between Hill City and Keystone. The operating railroad preserves an unusually immersive piece of nineteenth- and early-twentieth-century transportation technology rather than displaying it motionless in a museum.', 'limited', 'https://www.1880train.com/', null, 'America/Denver', now()),
  ('South Dakota State Railroad Museum', 'south-dakota-state-railroad-museum', 'weird-history', 43.9317, -103.57371, 'Hill City', 'SD', 'The state railroad museum interprets locomotives, depots, tools and the rail systems that shaped mining and settlement across South Dakota. Its Hill City location beside an operating heritage railroad creates a concentrated stop for machinery and transportation history.', 'limited', 'https://www.sdsrm.org/', null, 'America/Denver', now()),
  ('D.C. Booth Historic National Fish Hatchery & Archives', 'dc-booth-historic-national-fish-hatchery-archives', 'weird-history', 44.48116, -103.86009, 'Spearfish', 'SD', 'A federal fish hatchery established in 1896 preserves old hatchery buildings, railcars, fisheries equipment and a national archive devoted to fish-culture history. The combination of working ponds and specialized historical machinery makes it considerably stranger than a conventional nature center.', 'limited', 'https://www.fws.gov/fish-hatchery/dc-booth-historic', null, 'America/Denver', now()),
  ('Termesphere Gallery', 'termesphere-gallery', 'roadside-oddities', 44.45744, -103.8258, 'Spearfish', 'SD', 'Artist Dick Termes paints complete scenes across suspended spheres designed to be viewed from every direction. Dozens of these rotating six-point-perspective paintings create a disorienting gallery where rooms, landscapes and figures wrap continuously around curved surfaces.', 'limited', 'https://termespheres.com/', null, 'America/Denver', now()),
  ('High Plains Western Heritage Center', 'high-plains-western-heritage-center', 'museums', 44.46794, -103.8129, 'Spearfish', 'SD', 'This regional museum brings together ranching, rodeo, mining, transportation and Indigenous history from the High Plains. Large artifacts and recreated environments make it a useful context stop for the stranger frontier and industrial locations scattered across western South Dakota.', 'limited', 'https://www.westernheritagecenter.com/', null, 'America/Denver', now()),
  ('Bridal Veil Falls', 'bridal-veil-falls', 'roadside-oddities', 44.4165, -103.88089, 'Spearfish', 'SD', 'A narrow waterfall drops about 60 feet down the limestone walls of Spearfish Canyon and can be seen from a roadside viewing area. Seasonal water flow and the sheer canyon setting make it one of the most accessible geological stops in the northern Black Hills.', 'roadside', 'https://gfp.sd.gov/parks/detail/spearfish-canyon-nature-area/', null, 'America/Denver', now()),
  ('Spearfish Falls', 'spearfish-falls', 'roadside-oddities', 44.35285, -103.92985, 'Savoy', 'SD', 'Spearfish Creek plunges roughly 47 feet over a rock ledge below the canyon community of Savoy. A public trail reaches the base, revealing a waterfall that was once largely hidden after hydroelectric development diverted water from the creek.', 'open', 'https://gfp.sd.gov/parks/detail/spearfish-canyon-nature-area/', null, 'America/Denver', now()),
  ('Roughlock Falls', 'roughlock-falls', 'roadside-oddities', 44.34971, -103.94354, 'Savoy', 'SD', 'Little Spearfish Creek breaks into multiple cascades as it drops through a narrow side canyon. Boardwalks and trails provide lawful access to a landscape whose layered rock and divided waterfall look far more secluded than its relatively easy approach suggests.', 'open', 'https://gfp.sd.gov/parks/detail/spearfish-canyon-nature-area/', null, 'America/Denver', now()),
  ('Mount Roosevelt Friendship Tower', 'mount-roosevelt-friendship-tower', 'weird-history', 44.39809, -103.75924, 'Deadwood', 'SD', 'Seth Bullock built this stone tower in 1919 as a memorial to his friend Theodore Roosevelt. Reaching it requires a short climb above Deadwood, where the handmade tower rises unexpectedly from the forest like a small medieval ruin.', 'open', 'https://www.deadwood.com/business/attractions/mt-roosevelt-memorial-friendship-tower/', null, 'America/Denver', now()),
  ('Days of ''76 Museum', 'days-of-76-museum', 'weird-history', 44.38573, -103.71581, 'Deadwood', 'SD', 'The museum preserves stagecoaches, firearms, wagons, rodeo material and objects tied to Deadwood''s frontier mythology. Its large vehicle collection and emphasis on the city''s deliberately revived Wild West identity make it more unusual than a standard town museum.', 'limited', 'https://www.deadwoodhistory.com/about-us/properties/days-of-76-museum/', null, 'America/Denver', now()),
  ('Historic Adams House', 'historic-adams-house', 'weird-history', 44.37225, -103.72676, 'Deadwood', 'SD', 'This 1892 Queen Anne house was abandoned with many of its furnishings still inside after the owner''s death and later restored as a museum. The unusually intact interior creates the feeling of entering a wealthy Deadwood household that simply stopped in time.', 'limited', 'https://www.deadwoodhistory.com/about-us/properties/historic-adams-house/', null, 'America/Denver', now()),
  ('Tatanka: Story of the Bison', 'tatanka-story-of-the-bison', 'weird-history', 44.39832, -103.71417, 'Deadwood', 'SD', 'A massive bronze tableau depicts Lakota riders driving a herd of bison over a cliff, surrounded by interpretation of the animal''s importance to Plains cultures. The installation combines monumental sculpture with a story about the near-destruction of North America''s bison herds.', 'limited', 'https://storyofthebison.com/', null, 'America/Denver', now()),
  ('The Brothel Deadwood', 'the-brothel-deadwood', 'weird-history', 44.37854, -103.72926, 'Deadwood', 'SD', 'Guided and self-guided tours occupy rooms used by one of Deadwood''s former brothels and interpret more than a century of tolerated prostitution in the town. The industry''s abrupt end after a 1980 federal raid gives the preserved rooms an unusually recent connection to Deadwood''s outlaw reputation.', 'limited', 'https://www.deadwoodhistory.com/about-us/properties/the-brothel-deadwood/', null, 'America/Denver', now()),
  ('Original Location of Nuttall & Mann''s Saloon No. 10', 'original-location-of-nuttall-manns-saloon-no-10', 'weird-history', 44.37819, -103.72904, 'Deadwood', 'SD', 'This Main Street location is traditionally identified with the saloon where Wild Bill Hickok was shot while playing poker in 1876. The original structure burned in 1879 and the exact historic footprint has been debated, so OddWay should present the stop as the commemorated/traditional location rather than a surviving original saloon.', 'limited', 'https://www.roadsideamerica.com/story/59155', null, 'America/Denver', now()),
  ('Historic Homestake Opera House', 'historic-homestake-opera-house', 'weird-history', 44.35183, -103.76683, 'Lead', 'SD', 'Homestake Mining Company built this elaborate opera house in 1914 for the community surrounding its enormous gold mine. A catastrophic fire gutted much of the interior in 1984, and the ongoing restoration leaves visitors with an unusual mix of grand architecture, ruins and functioning performance space.', 'limited', 'https://www.homestakeoperahouse.org/', null, 'America/Denver', now()),
  ('Black Hills Mining Museum', 'black-hills-mining-museum', 'weird-history', 44.35172, -103.76713, 'Lead', 'SD', 'Displays interpret the machinery, geology and underground labor of the Homestake era, including a recreated mine experience beneath the museum. It is one of the best places to understand the industrial system that hollowed out the hills below Lead for more than a century.', 'limited', 'https://blackhillsminingmuseum.com/', null, 'America/Denver', now()),
  ('Old Fort Meade Museum', 'old-fort-meade-museum', 'weird-history', 44.40944, -103.47111, 'Fort Meade', 'SD', 'The museum occupies part of the historic military post established in 1878 near present-day Sturgis. Fort Meade''s cavalry history, surviving post buildings and long association with the Black Hills gold-rush era make the complex a substantial military-history detour.', 'limited', 'https://www.fortmeademuseum.org/', null, 'America/Denver', now()),
  ('Sturgis Motorcycle Museum & Hall of Fame', 'sturgis-motorcycle-museum-hall-of-fame', 'weird-history', 44.41448, -103.50871, 'Sturgis', 'SD', 'Historic and custom motorcycles document the machines and personalities behind the Sturgis Motorcycle Rally. The collection gives permanent form to a gathering that transforms this small Black Hills city into one of America''s largest motorcycle spectacles each year.', 'open', 'https://www.sturgismuseum.com/', null, 'America/Denver', now()),
  ('Tri-State Museum', 'tri-state-museum', 'museums', 44.6741, -103.85274, 'Belle Fourche', 'SD', 'The museum collects ranching, rodeo, Indigenous, military and settlement artifacts from the corners of South Dakota, Wyoming and Montana. Its location beside the Geographic Center monument makes it a natural extension of one of Belle Fourche''s strangest claims to fame.', 'open', 'https://thetristatemuseum.com/', null, 'America/Denver', now()),
  ('Thunderhead Falls', 'thunderhead-falls', 'roadside-oddities', 44.05764, -103.41325, 'Rapid City', 'SD', 'A waterfall rushes from a tunnel blasted through the rock during an abandoned attempt to divert water for gold mining. Visitors follow a short path into the canyon to see where human engineering accidentally created one of the Black Hills'' more unusual waterfall attractions.', 'limited', 'https://www.thunderheadfalls.com/', null, 'America/Denver', now()),
  ('Black Hills Caverns', 'black-hills-caverns', 'roadside-oddities', 44.06079, -103.35634, 'Rapid City', 'SD', 'Guided tours descend through layered limestone chambers filled with stalactites, stalagmites and other cave formations. The caverns were known to Indigenous people before later prospectors entered them during the Black Hills gold rush.', 'limited', 'https://www.blackhillscaverns.com/', null, 'America/Denver', now()),
  ('Wonderland Cave', 'wonderland-cave', 'roadside-oddities', 44.27383, -103.50126, 'Nemo', 'SD', 'This privately operated cave sends visitors down hundreds of steps through narrow passages and chambers in the northern Black Hills. Its long history as a roadside cave attraction adds another layer to a region where underground tourism developed alongside mining.', 'limited', 'https://wonderlandcave.com/', null, 'America/Denver', now()),
  ('Rushmore Cave', 'rushmore-cave', 'roadside-oddities', 43.8742, -103.33203, 'Keystone', 'SD', 'The cave beneath Rush Mountain contains twisting passages and rooms decorated with flowstone and other formations. Guided access makes the underground geology itself the OddWay draw, separate from the amusement attractions developed above ground.', 'limited', 'https://www.rushmtn.com/rushmore-cave/', null, 'America/Denver', now()),
  ('Four Mile Old West Town', 'four-mile-old-west-town', 'museums', 43.73302, -103.67324, 'Custer', 'SD', 'A collection of historic and reconstructed buildings forms a deliberately rough-edged frontier town outside Custer. Visitors walk through cabins, a saloon, jail and other structures filled with artifacts rather than encountering a polished modern museum interior.', 'limited', 'https://fourmileoldwesttown.com/', null, 'America/Denver', now()),
  ('1881 Courthouse Museum', '1881-courthouse-museum', 'weird-history', 43.76623, -103.6015, 'Custer', 'SD', 'Custer County''s former courthouse preserves courtroom fixtures, jail spaces and collections tied to the Black Hills gold rush. The old civic building''s cells and period rooms give it a stronger sense of place than collections relocated into a purpose-built museum.', 'limited', 'https://www.1881courthousemuseum.org/', null, 'America/Denver', now()),
  ('Big Rock Park & Custer Skywalk', 'big-rock-park-custer-skywalk', 'roadside-oddities', 43.76464, -103.59783, 'Custer', 'SD', 'A steep city park leads to oversized painted letters and a hilltop overlook above Custer. The hand-built stairways, rock outcrops and giant lettering turn an ordinary municipal hillside into a quirky walkable landmark.', 'open', 'https://www.cityofcuster.com/parks-and-recreation/page/big-rock-park', null, 'America/Denver', now()),
  ('Needle''s Eye', 'needles-eye', 'roadside-oddities', 43.84165, -103.54603, 'Custer State Park', 'SD', 'A tall granite spire contains a narrow opening that gives the formation its needle-and-thread name. It sits directly beside the Needles Highway, where weathered granite towers create some of the state''s most improbable natural shapes.', 'roadside', 'https://gfp.sd.gov/parks/detail/custer-state-park/', null, 'America/Denver', now()),
  ('Needles Eye Tunnel', 'needles-eye-tunnel', 'roadside-oddities', 43.8415, -103.54565, 'Custer State Park', 'SD', 'This one-lane tunnel was cut through solid granite immediately beside the Needle''s Eye formation. Its extremely narrow opening forces modern vehicles through a passage designed around the landscape rather than removing the rock entirely.', 'limited', 'https://gfp.sd.gov/parks/detail/custer-state-park/', null, 'America/Denver', now()),
  ('Iron Mountain Road Pigtail Bridges', 'iron-mountain-road-pigtail-bridges', 'roadside-oddities', 43.86938, -103.43557, 'Keystone', 'SD', 'Wooden bridges and looping road segments allow Iron Mountain Road to curl back over itself while climbing through the Black Hills. These so-called pigtail bridges are a deliberately theatrical piece of highway engineering designed to make the drive part of the attraction.', 'roadside', 'https://www.travelsouthdakota.com/trip-ideas/story-iron-mountain-road', null, 'America/Denver', now()),
  ('Mount Coolidge Fire Tower', 'mount-coolidge-fire-tower', 'roadside-oddities', 43.74473, -103.48145, 'Custer State Park', 'SD', 'A stone fire tower built by the Civilian Conservation Corps sits atop one of Custer State Park''s highest accessible summits. A narrow seasonal road reaches the tower, where the Black Hills spread out in nearly every direction.', 'limited', 'https://gfp.sd.gov/parks/detail/custer-state-park/', null, 'America/Denver', now()),
  ('Black Elk Peak Lookout Tower', 'black-elk-peak-lookout-tower', 'roadside-oddities', 43.86596, -103.5311, 'Black Elk Wilderness', 'SD', 'A stone fire lookout constructed by the Civilian Conservation Corps crowns the highest point east of the Rocky Mountains in the United States. The abandoned lookout is reached only by hiking and feels like a small mountain fortress above the surrounding granite spires.', 'limited', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=25879', null, 'America/Denver', now()),
  ('Cathedral Spires', 'cathedral-spires', 'roadside-oddities', 43.84173, -103.53527, 'Custer State Park', 'SD', 'Clusters of narrow granite pinnacles rise almost vertically above the forest and form one of the Black Hills'' most dramatic rock landscapes. A trail from the Needles Highway reaches the base of formations that resemble an enormous natural stone cathedral.', 'limited', 'https://gfp.sd.gov/parks/detail/custer-state-park/', null, 'America/Denver', now()),
  ('Sylvan Lake', 'sylvan-lake', 'roadside-oddities', 43.84569, -103.563, 'Custer State Park', 'SD', 'A small dam created this lake between giant granite formations in the late nineteenth century. The resulting combination of artificial water and natural boulders is so visually unusual that it has become one of the defining landscapes of the Black Hills.', 'open', 'https://gfp.sd.gov/parks/detail/custer-state-park/', null, 'America/Denver', now()),
  ('Evans Plunge Mineral Springs', 'evans-plunge-mineral-springs', 'weird-history', 43.44149, -103.4808, 'Hot Springs', 'SD', 'A naturally warm mineral spring feeds a large indoor pool first developed as a commercial plunge in 1890. The constant flow of spring water links a modern recreation facility directly to the geology that gave Hot Springs its name.', 'limited', 'https://www.evansplunge.com/', null, 'America/Denver', now()),
  ('Black Hills Wild Horse Sanctuary', 'black-hills-wild-horse-sanctuary', 'weird-history', 43.31293, -103.60588, 'Hot Springs', 'SD', 'Thousands of acres south of Hot Springs provide protected range for wild mustangs and other horses. Access to the herds is controlled and tours require advance arrangements; visitors should use the official visitor center and never drive into sanctuary lands without authorization.', 'limited', 'https://www.wildmustangs.com/', null, 'America/Denver', now()),
  ('Hotel Alex Johnson', 'hotel-alex-johnson', 'haunted', 44.0804, -103.22754, 'Rapid City', 'SD', 'The historic downtown hotel openly promotes long-running reports of unexplained activity associated with several rooms and areas of the building. These stories are hotel lore rather than verified events, but the property is one of the rare South Dakota businesses that directly interprets its own paranormal reputation.', 'limited', 'https://www.alexjohnson.com/paranormal/', null, 'America/Denver', now()),
  ('Elks Theatre', 'elks-theatre', 'weird-history', 44.08059, -103.22668, 'Rapid City', 'SD', 'A movie theater has operated on this downtown site for generations, preserving an increasingly uncommon piece of small-city cinema history. Its old auditorium and long entertainment history make it a worthwhile architectural stop in Rapid City''s historic core.', 'open', 'https://www.visitrapidcity.com/listing/elks-theatre/1109/', null, 'America/Denver', now()),
  ('Berlin Wall Exhibit at Memorial Park', 'berlin-wall-exhibit-at-memorial-park', 'weird-history', 44.08606, -103.22784, 'Rapid City', 'SD', 'Two original sections of the Berlin Wall stand outdoors with tank traps and interpretive panels in Memorial Park. Finding physical pieces of one of Europe''s most famous Cold War barriers in western South Dakota makes the exhibit an unexpectedly strong historical oddity.', 'open', 'https://www.visitrapidcity.com/things-to-do/historic-sites/berlin-wall/', null, 'America/Denver', now()),
  ('Storybook Island', 'storybook-island', 'roadside-oddities', 44.06999, -103.26435, 'Rapid City', 'SD', 'This free children''s park fills a wooded island-like landscape with oversized storybook characters, castles and fantasy scenes. Decades of locally built figures give it the handmade quality of an old roadside fairy-tale attraction rather than a modern theme park.', 'limited', 'https://storybookisland.org/', null, 'America/Denver', now()),
  ('Bear Country USA', 'bear-country-usa', 'roadside-oddities', 43.97711, -103.29922, 'Rapid City', 'SD', 'Visitors drive through large enclosures containing black bears and other North American wildlife before reaching a walk-through area. The concentration of free-roaming bears visible from inside a vehicle makes the attraction one of the Black Hills'' stranger roadside experiences.', 'limited', 'https://bearcountryusa.com/', null, 'America/Denver', now()),
  ('Heavy Metal Sue', 'heavy-metal-sue', 'roadside-oddities', 45.02324, -102.03625, 'Faith', 'SD', 'Sculptor John Lopez assembled this enormous Tyrannosaurus rex from scrap metal in the town near where the famous fossil Sue was discovered. The sculpture turns one of South Dakota''s most consequential paleontological stories into a permanent piece of industrial-looking roadside art.', 'open', 'https://www.travelsouthdakota.com/trip-ideas/awesome-roadside-attractions', null, 'America/Denver', now()),
  ('Al''s Oasis Giant Bison', 'als-oasis-giant-bison', 'roadside-oddities', 43.80299, -99.38236, 'Oacoma', 'SD', 'An oversized bison stands outside the long-running Al''s Oasis travel stop near the Missouri River. It continues the South Dakota tradition of using giant animals as highway landmarks and photo opportunities.', 'open', 'https://www.als-oasis.com/', null, 'America/Chicago', now()),
  ('Armed Forces Display & Gifts', 'armed-forces-display-gifts', 'museums', 44.05912, -102.47416, 'Wasta', 'SD', 'A privately assembled collection of military vehicles, uniforms, weapons and memorabilia occupies an unlikely roadside location in tiny Wasta. Travelers should check current hours before making a special trip because access can be seasonal or irregular.', 'limited', 'https://www.travelsouthdakota.com/wasta', null, 'America/Denver', now()),
  ('Galena Ghost Town', 'galena-ghost-town', 'weird-history', 44.3336, -103.64103, 'Galena', 'SD', 'Mining booms and busts left Galena with scattered historic buildings and remnants of a once-busier Black Hills settlement. The community is not entirely abandoned, so visitors should stay on public roads and treat occupied or posted structures as private property.', 'roadside', 'https://www.sdpb.org/rural-life-and-history/2020-10-13/galena-the-ghost-town-that-refuses-to-die', null, 'America/Denver', now()),
  ('Okaton Ghost Town', 'okaton-ghost-town', 'weird-history', 43.8861, -100.89181, 'Okaton', 'SD', 'Weathered houses, a former school, railroad remnants and grain-elevator structures survive around the tiny community of Okaton. The remaining buildings are private property even when they appear abandoned, so this is a photograph-from-public-roads stop rather than an urbex destination.', 'roadside', 'https://www.atlasobscura.com/places/okaton-ghost-town', null, 'America/Denver', now()),
  ('Fort Sisseton Historic State Park', 'fort-sisseton-historic-state-park', 'weird-history', 45.6594, -97.52827, 'Lake City', 'SD', 'More than a dozen surviving nineteenth-century military buildings stand at a remote former frontier post on the Coteau des Prairies. Barracks, officers'' quarters and support structures create one of the state''s most complete preserved military complexes.', 'limited', 'https://gfp.sd.gov/parks/detail/fort-sisseton-historic-state-park/', null, 'America/Chicago', now()),
  ('Sitting Bull Monument', 'sitting-bull-monument', 'weird-history', 45.51694, -100.48518, 'Mobridge', 'SD', 'A stone bust by sculptor Korczak Ziolkowski marks the South Dakota site traditionally identified with the relocated remains of Hunkpapa Lakota leader Sitting Bull. The history of that relocation is disputed and sensitive, so the site should be presented respectfully as a memorial and gravesite rather than a roadside novelty.', 'limited', 'https://mobridge.org/sitting-bull-monument', null, 'America/Chicago', now()),
  ('Sakakawea Monument', 'sakakawea-monument', 'weird-history', 45.51583, -100.48792, 'Mobridge', 'SD', 'A monument to Sakakawea stands only a short distance from the Sitting Bull memorial above the Missouri River. The isolated location links Lewis and Clark commemoration with a landscape carrying much deeper Indigenous history.', 'limited', 'https://mobridge.org/', null, 'America/Chicago', now()),
  ('Joseph N. Nicollet Tower & Interpretive Center', 'joseph-n-nicollet-tower-interpretive-center', 'weird-history', 45.65934, -97.13327, 'Sisseton', 'SD', 'An approximately 75- to 80-foot observation tower honors French cartographer Joseph Nicollet and overlooks the Coteau des Prairies. From the upper platform visitors can see portions of three states and a glacial landscape that Nicollet helped map in the nineteenth century.', 'limited', 'https://www.sissetonmuseum.com/nicollet-tower', null, 'America/Chicago', now()),
  ('Historic Milbank Grist Mill', 'historic-milbank-grist-mill', 'weird-history', 45.22218, -96.61914, 'Milbank', 'SD', 'A reconstructed water-powered grist mill interprets the milling industry that once used the nearby creek for power. Its working machinery and unusual stone architecture make the site a compact surviving example of early prairie industry.', 'limited', 'https://www.travelsouthdakota.com/milbank', null, 'America/Chicago', now()),
  ('Stavig House Museum', 'stavig-house-museum', 'weird-history', 45.66148, -97.05258, 'Sisseton', 'SD', 'This large 1916 home combines Victorian and Arts and Crafts details and remained connected with the same Norwegian immigrant family for generations. Original family material allows the museum to tell migration and settlement history through one unusually intact household.', 'limited', 'https://www.sissetonmuseum.com/stavig-house', null, 'America/Chicago', now()),
  ('Redlin Art Center', 'redlin-art-center', 'museums', 44.88651, -97.0606, 'Watertown', 'SD', 'A monumental brick museum houses a large collection of Terry Redlin''s nostalgic wildlife and rural paintings. The purpose-built center gives one commercial artist an unexpectedly grand, almost shrine-like presence along Interstate 29.', 'open', 'https://www.redlinart.com/', null, 'America/Chicago', now()),
  ('Goss Opera House', 'goss-opera-house', 'weird-history', 44.89979, -97.11261, 'Watertown', 'SD', 'Built in the nineteenth century, the restored opera house contains performance, gallery and event spaces above downtown Watertown. Its survival preserves the elaborate kind of upper-floor entertainment venue that once appeared in prairie commercial blocks.', 'limited', 'https://thegossoperahouse.com/', null, 'America/Chicago', now()),
  ('National Music Museum', 'national-music-museum', 'museums', 42.78294, -96.92647, 'Vermillion', 'SD', 'Thousands of rare instruments represent centuries of musical technology, including highly specialized, ornate and experimental objects. The depth of the collection makes this university museum one of South Dakota''s strongest genuinely unusual indoor stops.', 'open', 'https://www.nmmusd.org/', null, 'America/Chicago', now()),
  ('Mead Museum', 'mead-museum', 'weird-history', 42.91365, -97.40277, 'Yankton', 'SD', 'The museum occupies the imposing former administration building of the Dakota Hospital for the Insane, later called the Human Services Center. Restored institutional architecture now houses regional exhibits while preserving the building''s much more complicated original history.', 'open', 'https://www.meadbuilding.org/', null, 'America/Chicago', now()),
  ('USS South Dakota Battleship Memorial', 'uss-south-dakota-battleship-memorial', 'weird-history', 43.54334, -96.76294, 'Sioux Falls', 'SD', 'A concrete outline marks the approximate dimensions of the World War II battleship USS South Dakota, with parts of the actual ship and a museum placed inside the footprint. The ground-level reconstruction communicates the scale of a vessel that would otherwise be impossible to bring inland.', 'limited', 'https://www.siouxfalls.gov/activities-recreation/parks-trails/park-directory/uss-south-dakota-battleship-memorial', null, 'America/Chicago', now()),
  ('Arc of Dreams', 'arc-of-dreams', 'roadside-oddities', 43.54992, -96.72464, 'Sioux Falls', 'SD', 'A massive stainless-steel arc rises from both banks of the Big Sioux River but deliberately leaves a gap high above the water. The missing section represents the leap required to turn a dream into reality and gives downtown Sioux Falls one of the state''s largest modern sculptures.', 'open', 'https://sculpturewalksiouxfalls.com/arc-of-dreams/', null, 'America/Chicago', now()),
  ('Ingalls Homestead', 'ingalls-homestead', 'museums', 44.36825, -97.5411, 'De Smet', 'SD', 'The homestead associated with the Ingalls family preserves the prairie setting made famous through Laura Ingalls Wilder''s writing. Reconstructed buildings and hands-on activities allow visitors to experience the exposed landscape that shaped several of her books.', 'limited', 'https://www.ingallshomestead.com/', null, 'America/Chicago', now()),
  ('Laura Ingalls Wilder Memorial Society Historic Homes', 'laura-ingalls-wilder-memorial-society-historic-homes', 'weird-history', 44.38664, -97.54389, 'De Smet', 'SD', 'The De Smet complex preserves several buildings directly connected with Laura Ingalls Wilder and her family, including the Surveyors'' House and Ingalls family home. The concentration of real locations makes the town unusually dense with sites that later became part of American literary mythology.', 'limited', 'https://discoverlaura.org/', null, 'America/Chicago', now()),
  ('De Smet Cemetery — Ingalls Family Graves', 'de-smet-cemetery-ingalls-family-graves', 'weird-history', 44.36768, -97.57007, 'De Smet', 'SD', 'Members of the Ingalls family are buried in this quiet prairie cemetery west of De Smet. The graves provide a real-world endpoint to people and events heavily fictionalized and mythologized through the Little House books and later television adaptations.', 'limited', 'https://discoverlaura.org/', null, 'America/Chicago', now()),
  ('Prairie Village', 'prairie-village', 'museums', 44.00609, -97.16756, 'Madison', 'SD', 'Historic buildings, agricultural machinery, steam equipment and railroad artifacts fill a large recreated prairie community. Annual demonstrations bring massive antique engines back to life, making the site particularly strong for travelers interested in obsolete machinery.', 'limited', 'https://prairievillage.org/', null, 'America/Chicago', now()),
  ('Fort Randall Historic Site', 'fort-randall-historic-site', 'weird-history', 43.05027, -98.56036, 'Pickstown', 'SD', 'Stone and brick remains mark the Missouri River military post established in 1856 and later abandoned. The ruined chapel and foundations survive beside the modern Fort Randall Dam, placing frontier military history against enormous twentieth-century infrastructure.', 'open', 'https://www.nps.gov/mnrr/learn/historyculture/fortrandall.htm', null, 'America/Chicago', now()),
  ('Verendrye Site', 'verendrye-site', 'weird-history', 44.35556, -100.37861, 'Fort Pierre', 'SD', 'A hill above Fort Pierre marks where the La Vérendrye expedition buried a lead plate in 1743 to claim the region for France. Schoolchildren found the plate in 1913, turning an otherwise ordinary bluff into physical evidence of an eighteenth-century imperial expedition.', 'open', 'https://www.fortpierre.com/', null, 'America/Chicago', now()),
  ('Oahe Chapel', 'oahe-chapel', 'weird-history', 44.45806, -100.38556, 'Pierre', 'SD', 'This small church is one of the few surviving buildings from the community displaced by construction of Oahe Dam and reservoir. It was moved before the rising water covered the original townsite, preserving a physical fragment of a vanished Missouri River settlement.', 'limited', 'https://history.sd.gov/preservation/oahechapel.aspx', null, 'America/Chicago', now()),
  ('Čhatkú Arts Center at Maȟpíya Lúta', 'hatk-arts-center-at-ma-p-ya-l-ta', 'weird-history', 43.07818, -102.58632, 'Pine Ridge', 'SD', 'The arts center holds a major collection of historical and contemporary Lakota art and supports hundreds of Native artists through exhibitions and sales. Its new facility opened in 2026 on the Maȟpíya Lúta campus, making it an important living cultural stop rather than a collection separated from the community it represents.', 'open', 'https://chatkuartscenter.mahpiyaluta.org/', null, 'America/Denver', now()),
  ('Ben Reifel Visitor Center & Fossil Preparation Lab', 'ben-reifel-visitor-center-fossil-preparation-lab', 'weird-history', 43.74908, -101.94166, 'Badlands National Park', 'SD', 'The main Badlands visitor center includes paleontology exhibits and a working fossil preparation lab where visitors can sometimes watch park staff prepare specimens recovered from the surrounding formations. It connects the surreal Badlands landscape directly with the extinct animals preserved inside its rocks.', 'open', 'https://www.nps.gov/badl/planyourvisit/visitor-centers.htm', null, 'America/Denver', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  timezone      = excluded.timezone,
  verified_at   = excluded.verified_at;

select count(*) as south_dakota from public.stops where state = 'SD';
